'use strict';
const D=['Mobile Devices','Networking','Hardware','Virtualization and Cloud Computing','Hardware and Network Troubleshooting'];
const app=document.getElementById('app');const KEY='a_plus_1201_sim_v2';
let state;try{state=JSON.parse(localStorage.getItem(KEY))||{history:[],bookmarks:[],attempts:[]}}catch(e){state={history:[],bookmarks:[],attempts:[]}}
let mode='home',exam=null,tick=null,chosenChip=null,navigatorOpen=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}};
function nav(s){document.querySelectorAll('aside button').forEach(b=>b.classList.toggle('active',b.id==='nav'+s))}
function stop(){if(tick)clearInterval(tick);tick=null}
function resetNavigation(){if(exam&&!confirm('Leave this unfinished exam?'))return;exam=null;stop();showHome()}
function showHome(){mode='home';nav('home');app.innerHTML=`<h1>Quiz Select</h1>${[['ordered','In-Order Exam Questions (PDF Questions 1–351)'],['sim','Simulator Mode'],['book','Bookmarked Questions'],['5','Quick (5)'],['10','Quick (10)'],['20','Quick (20)'],['40','Quick (40)'],['100','Full Exam (100)']].map(([v,t],i)=>`<label class="line">${t}<input type="radio" name="homeMode" value="${v}" ${i===0?'checked':''}></label>`).join('')}<div class="actions"><button class="primary" onclick="startHome()">START</button></div><section class="pbq-direct"><h2>PBQ Questions — Direct Access</h2><p>These questions are also included in the 1–351 in-order exam. Select a number to open that PDF question directly.</p><div class="pbq-direct-grid">${[340,341,342,343,344,345,346,347,348,349,350,351].map(id=>`<button class="secondary" onclick="openPDFQuestion(${id})">Question ${id}</button>`).join('')}</div></section>`}
function openPDFQuestion(id){const ordered=[...QUESTIONS].sort((a,b)=>a.id-b.id);const idx=ordered.findIndex(q=>q.id===id);if(idx<0){alert('PDF Question '+id+' is missing from the question data.');return}startExam(ordered,ordered.length,0,false,true);exam.index=idx;renderExam()}
function startHome(){let v=document.querySelector('input[name=homeMode]:checked').value;let pool=v==='book'?QUESTIONS.filter(q=>state.bookmarks.includes(q.id)):QUESTIONS;if(!pool.length){alert('No bookmarked questions yet.');return}if(v==='ordered'){startExam([...QUESTIONS].sort((a,b)=>a.id-b.id),QUESTIONS.length,0,false,true);return}let count=v==='sim'||v==='100'?100:v==='book'?pool.length:Number(v);startExam(pool,count,v==='sim'||v==='100'?150:0)}
function showCustom(){mode='custom';nav('custom');app.innerHTML=`<h1>Mode</h1><label class="line">Questions <input type="radio" name="format" value="questions" checked></label><h1>Domain Selection</h1><label class="line">All <input type="checkbox" id="all" checked onchange="toggleAll(this.checked)"></label>${D.map((d,i)=>`<label class="line">${esc(d)}<input type="checkbox" class="dom" value="${i+1}" checked onchange="updateAll()"></label>`).join('')}<h2>Number of questions</h2><input type="number" id="count" min="1" max="351" value="20"><h2>Timer (minutes, 0 = untimed)</h2><input type="number" id="mins" min="0" max="300" value="0"><div class="actions"><button class="primary" onclick="startCustom()">START</button><button class="primary" onclick="showCustom()">RESET</button></div>`}
function toggleAll(v){document.querySelectorAll('.dom').forEach(x=>x.checked=v)}function updateAll(){document.getElementById('all').checked=[...document.querySelectorAll('.dom')].every(x=>x.checked)}
function startCustom(){let ds=[...document.querySelectorAll('.dom:checked')].map(x=>+x.value),pool=QUESTIONS.filter(q=>ds.includes(q.domain));if(!pool.length){alert('Select at least one domain with questions.');return}startExam(pool,Math.max(1,+document.getElementById('count').value||20),Math.max(0,+document.getElementById('mins').value||0),false)}
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function startExam(pool,count,minutes,flash=false,inOrder=false){stop();navigatorOpen=false;let items=(inOrder?[...pool]:shuffle(pool)).slice(0,Math.min(count,pool.length));exam={items,index:0,answers:{},revealed:{},placements:{},start:Date.now(),end:minutes?Date.now()+minutes*60000:null,paused:false,remaining:null,flash};mode='exam';renderExam();if(exam.end)tick=setInterval(updateClock,1000)}
function current(){return exam.items[exam.index]};function answer(){return exam.answers[current().id]||[]}
function updateClock(){if(!exam||!exam.end||exam.paused)return;let left=Math.max(0,Math.ceil((exam.end-Date.now())/1000));let e=document.getElementById('clock');if(e)e.textContent='TIME LEFT '+fmt(left);if(left===0)finish(true)}
function fmt(n){return `${Math.floor(n/3600)}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function togglePause(){if(!exam.end)return;if(exam.paused){exam.end=Date.now()+exam.remaining;exam.paused=false}else{exam.remaining=Math.max(0,exam.end-Date.now());exam.paused=true}renderExam()}
function bookmark(){if(exam.paused)return;let id=current().id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();renderExam()}
function selectAnswer(key,multi){if(exam.paused)return;let q=current(),a=answer();if(exam.revealed[q.id])return;exam.answers[q.id]=multi?(a.includes(key)?a.filter(x=>x!==key):[...a,key]):[key];renderExam()}
function renderExam(){if(!exam)return;let q=current(),a=answer(),rev=exam.revealed[q.id],isBook=state.bookmarks.includes(q.id);nav('');app.innerHTML=`<div class="questionbar"><div>QUESTION ${exam.index+1} / ${exam.items.length}<br><span id="clock">${exam.end?'TIME LEFT '+fmt(Math.max(0,Math.ceil(((exam.paused?Date.now()+exam.remaining:exam.end)-Date.now())/1000))):'UNTIMED'}</span></div><div><button title="Bookmark" onclick="bookmark()" style="color:${isBook?'#41cb63':'#555'}">${isBook?'🔖':'♧'}</button><button title="Pause timer" onclick="togglePause()">${exam.paused?'▶':'Ⅱ'}</button><button title="Toggle question navigator" aria-expanded="${navigatorOpen}" onclick="questionList()">☰</button><button title="Exit exam" aria-label="Exit exam" onclick="exitExam()">✕</button></div></div>${navigatorOpen?navigatorHTML():''}<div class="muted">${esc(D[q.domain-1]||'Unclassified')} · PDF Question ${q.id} · Page ${q.page}</div><div class="question">${esc(q.stem)}</div>${q.pbq?pbqHTML(q):''}${q.options.length?`<div>${q.options.map(o=>`<label class="choice ${rev?(q.answer.includes(o.key)?'correct':a.includes(o.key)?'wrong':''):''}"><input type="${q.answer.length>1?'checkbox':'radio'}" name="q" ${a.includes(o.key)?'checked':''} ${rev?'disabled':''} onchange="selectAnswer('${o.key}',${q.answer.length>1})"><b>${o.key}.</b> ${esc(o.text)}</label>`).join('')}</div>`:q.pbq&&![340,341,342,343,344,345,346,347,348,349,350,351].includes(q.id)?'<p class="muted">Use the interactive response workspace below. Complete the diagram and submit your selections. Some source diagrams require an independently verified key before a reliable score can be assigned.</p>':''}${rev&&![342,344].includes(q.id)?`<div class="review"><b>PDF answer:</b> ${q.answer.length?q.answer.join(', '):'Not provided in source'}<br><b>Your selection:</b> ${a.length?a.join(', '):'None'}<br><b>Explanation from PDF:</b> ${esc(q.explanation||'No explanation supplied in the source PDF.')}</div>`:''}<div class="actions"><button class="secondary" onclick="move(-1)" ${exam.index===0?'disabled':''}>← Previous</button>${q.pbq?'':`<button class="secondary" onclick="reveal()">${rev?'Answer revealed':'Reveal Answer'}</button>`}<button class="primary" onclick="move(1)">${exam.index===exam.items.length-1?'Finish →':'Next →'}</button></div><div class="actions"><button class="secondary" onclick="finish(false)">Finish Exam</button></div>`;if(exam.paused){const clock=document.getElementById('clock');if(clock)clock.insertAdjacentHTML('afterend',' <span class="pause-tag">PAUSED</span>');app.querySelectorAll('input, select, .actions button, .dropzone button, .chip').forEach(el=>{if(el.matches('input,select,button'))el.disabled=true;else{el.style.pointerEvents='none';el.setAttribute('draggable','false')}})}updateClock()}
function printer346HTML(q){
 const names=['Rollers','Duplexer','Ink cartridge','Toner','Fuser'];
 const placements=exam.placements[q.id]||{};
 const labels=['Upper-left component','Upper-right component','Tray 2 (Letter)','Tray 3 (Legal)'];
 const expected=['Fuser','','','Rollers'];
 const submitted=!!exam.printerSubmitted?.[346];
 const correct=labels.map((_,i)=>(placements[i]||'')===expected[i]);
 const selects=labels.map((label,i)=>`<label class="printer-slot printer-slot-${i} ${submitted?(correct[i]?'slot-correct':'slot-incorrect'):''}" title="${label}"><span class="sr-only">${label}</span><select aria-label="${label}" ${exam.paused?'disabled':''} onchange="setPrinter346(${i},this.value)"><option value="">— Select —</option>${names.map(n=>`<option value="${n}" ${placements[i]===n?'selected':''}>${n}</option>`).join('')}</select>${submitted?`<span class="slot-status">${correct[i]?'✓':'✕'}</span>`:''}</label>`).join('');
 return `<section class="printer-pbq"><h2>Printer components — Question 346</h2><p class="muted">Select the faulty printer components in their matching boxes. Leave unaffected locations blank. Not every option is needed.</p><div class="printer-stage"><img src="assets/printer_346.png" alt="Printer diagram showing four component dropdown locations">${selects}</div><div class="actions"><button class="secondary" ${exam.paused?'disabled':''} onclick="exam.placements[346]={};exam.printerSubmitted??={};exam.printerSubmitted[346]=false;renderExam()">Reset All</button><button class="primary" ${exam.paused?'disabled':''} onclick="submitPrinter346()">Submit Answers</button></div>${submitted?`<div class="review" aria-live="polite"><b>PBQ Review — ${correct.filter(Boolean).length} of 4 locations correct</b><p>Green = correct; red = incorrect. Blank is correct for unaffected components.</p>${labels.map((label,i)=>`<p><strong>${correct[i]?'✓ Correct':'✕ Incorrect'} — ${label}:</strong> ${esc(placements[i]||'Left blank')}${correct[i]?'':`. Correct selection: ${expected[i]||'Leave blank'}`}</p>`).join('')}<p class="muted"><b>Explanation:</b> Each printer fault must be associated with its actual component; unaffected components should remain unselected. <b>Remember Tip:</b> Identify the stage of the printing process before replacing parts.</p></div>`:''}</section>`;
}
function setPrinter346(i,v){if(exam.paused)return;exam.placements[346]??={};if(v)exam.placements[346][i]=v;else delete exam.placements[346][i];exam.printerSubmitted??={};exam.printerSubmitted[346]=false;}
function submitPrinter346(){if(exam.paused)return;exam.printerSubmitted??={};exam.printerSubmitted[346]=true;renderExam();}
function workstation345HTML(q){
 const fields=[['Processor',['Intel Core i3','Intel Core i7','Intel Xeon','ARM Cortex']],['Video card',['Discrete GPU','On board video']],['RAM',['16GB DDR5 ECC','4GB DDR5 ECC','8GB DDR5','8GB SODIMM','16GB DDR5']],['Sound card',['On board sound','7.1 surround card']],['Peripherals',['Headset','External microphone','Web cam']],['Hard drive',['500GB HDD','4TB HDD','256GB SSD','1TB SSD']]];
 const keys=['gaming','family'];let tab=exam.workstationTab||'gaming';let picks=exam.placements[345]||{};let values=picks[tab]||{};
 const defaults={gaming:['Intel Core i7','Discrete GPU','16GB DDR5','7.1 surround card','Headset','1TB SSD'],family:['Intel Core i3','On board video','4GB DDR5 ECC','On board sound','Web cam','500GB HDD']};
 const options=(arr,val)=>'<option value="">— Select —</option>'+arr.map(x=>`<option value="${esc(x)}" ${val===x?'selected':''}>${esc(x)}</option>`).join('');
 return `<section class="workstation-pbq"><h2>Question 345 — Gaming and Family Workstation Configuration</h2><p>Configure both workstations according to the requirements above. Select a component for each category, then switch to the other workstation. Your selections are preserved.</p><div class="workstation-tabs">${keys.map(k=>`<button class="secondary ${tab===k?'selected-tab':''}" ${exam.paused?'disabled':''} onclick="exam.workstationTab='${k}';renderExam()">${k==='gaming'?'Gaming workstation':'Family workstation'}</button>`).join('')}</div><div class="workstation-stage"><img src="assets/workstation_${tab}.jpg" alt="${tab} workstation diagram from source PDF; interactive selectors replace the printed selections">${fields.map(([label,opts],i)=>`<label class="workstation-field workstation-field-${i}"><span class="sr-only">${label}</span><select aria-label="${tab} ${label}" ${exam.paused?'disabled':''} onchange="setWorkstation345('${tab}',${i},this.value)">${options(opts,values[i]||'')}</select></label>`).join('')}</div><div class="actions"><button class="secondary" ${exam.paused?'disabled':''} onclick="exam.placements[345]??={};exam.placements[345]['${tab}']={};exam.workstationSubmitted=false;renderExam()">Reset ${tab==='gaming'?'Gaming':'Family'}</button><button class="primary" ${exam.paused?'disabled':''} onclick="exam.workstationSubmitted=true;renderExam()">Submit Both Workstations</button></div>${exam.workstationSubmitted?`<div class="review"><b>PBQ Review — Question 345</b><p>Comparison with the example configurations shown in the supplied PDF:</p>${keys.map(k=>`<h3>${k==='gaming'?'Gaming':'Family'} workstation</h3>${fields.map(([label],i)=>{let v=picks[k]?.[i]||'Not selected';return `<p><b>${label}:</b> ${esc(v)} — ${v===defaults[k][i]?'Matches PDF example':v==='Not selected'?'Not selected':'Differs from PDF example'} (Reference: ${esc(defaults[k][i])})</p>`}).join('')}`).join('')}<p><b>Explanation:</b> Gaming builds prioritize graphics performance, cooling, and sufficient power. Family builds prioritize dependable everyday performance and practical peripherals.</p><p><b>Remember Tip:</b> Select parts for the workload rather than choosing the highest specification in every category.</p></div>`:''}</section>`;
}
function setWorkstation345(tab,i,value){if(exam.paused)return;exam.placements[345]??={};exam.placements[345][tab]??={};if(value)exam.placements[345][tab][i]=value;else delete exam.placements[345][tab][i];exam.workstationSubmitted=false;}


// Q350 is a two-part troubleshooting HOTSPOT, not a drag-and-drop exercise.
function voip350State(){exam.voip350??={part:1,tab:'Site A Commands',logs:{},cause:'',action:'',submitted:false};return exam.voip350}
function voip350HTML(q){let v=voip350State(),tabs=['Site A Commands','Site A VoIP','Site B Commands','Site B VoIP'],part=v.part;
let cause=['Packet loss','Jitter','Bandwidth','Latency'],actions=['Assign a static IP address to the user’s workstation.','Plug an Ethernet cable into the user workstation.','Change the default route to the user’s workstation.','Replace the user’s workstation.','Ask the user to restart the workstation.'];
return `<section class="voip-pbq"><h2>Question 350 — Troubleshoot Dropped VoIP Calls</h2><p>Investigate both sites using a Windows-style Command Prompt. The output is simulated practice data, not a transcript of the original PDF.</p><div class="voip-instructions"><h3>How to use the command terminals</h3><ol><li>Select <b>Site A Commands</b> or <b>Site B Commands</b> to inspect network connectivity.</li><li>Click the command line, type <code>help</code>, then press <b>Enter</b> (or click Run).</li><li>Run <code>ipconfig /all</code> first and find the <b>Default Gateway</b>. Then ping that address (for example, <code>ping 192.168.10.1</code> at Site A). Use <code>pathping</code> with the same address to investigate packet loss.</li><li>Use <b>Site A VoIP</b> and <b>Site B VoIP</b> for simulated call-quality status, then compare results.</li><li>Complete both Part 1 and Part 2, then click <b>Submit Answers</b> for feedback.</li></ol><p><b>Tip:</b> <code>cls</code> clears Command Prompt; <code>help</code> lists the supported practice commands. These commands run only inside this simulation.</p></div><div class="voip-parts"><button class="${part===1?'voip-active':''}" onclick="voipPart(1)" ${exam.paused?'disabled':''}>Part 1 — Identify the cause</button><button class="${part===2?'voip-active':''}" onclick="voipPart(2)" ${exam.paused?'disabled':''}>Part 2 — Resolve the issue</button></div><div class="voip-layout"><div class="voip-tabs">${tabs.map(t=>`<button class="${v.tab===t?'voip-active':''}" onclick="voipTab('${t}')" ${exam.paused?'disabled':''}>${t}</button>`).join('')}</div><div class="voip-terminal"><div class="win-titlebar"><span class="win-app-icon">C:\\_</span><span>Administrator: Command Prompt — ${esc(v.tab)}</span><span class="win-window-controls" aria-hidden="true">— &nbsp; □ &nbsp; ×</span></div><div class="win-terminal-body"><div class="win-version">Microsoft Windows [Version 10.0.19045.0]<br>(c) Microsoft Corporation. All rights reserved.<br><span class="win-note">Practice simulation • Site ${v.tab.startsWith('Site A')?'A':'B'} • Part ${part}</span></div><pre id="voip-output">${esc(v.logs[part+'|'+v.tab]||'')}</pre><form onsubmit="voipCommand(event)"><label for="voip-input">C:\\Users\\${v.tab.startsWith('Site A')?'SiteA':'SiteB'}&gt;</label><input id="voip-input" autocomplete="off" spellcheck="false" aria-label="Windows Command Prompt command" placeholder="type help and press Enter" ${exam.paused?'disabled':''}><button ${exam.paused?'disabled':''}>Run</button></form></div></div></div><div class="voip-response"><h3>${part===1?'What is the most likely cause of the dropped calls?':'Which action should the technician perform first?'}</h3>${(part===1?cause:actions).map(x=>`<label class="voip-choice"><input type="radio" name="voip-choice" ${v[part===1?'cause':'action']===x?'checked':''} onchange="voipSelect('${part===1?'cause':'action'}',this.value)" value="${esc(x)}" ${exam.paused?'disabled':''}>${esc(x)}</label>`).join('')}</div><div class="actions"><button class="secondary" onclick="voipReset()" ${exam.paused?'disabled':''}>Reset PBQ</button><button class="primary" onclick="voipSubmit()" ${exam.paused?'disabled':''}>Submit Answers</button></div>${v.submitted?`<div class="review"><b>PBQ Review</b><p>Part 1: ${v.cause==='Packet loss'?'✓ Correct':'✕ Incorrect'} — ${esc(v.cause||'Not selected')}. Correct: Packet loss.</p><p>Part 2: ${v.action===actions[1]?'✓ Correct':'✕ Incorrect'} — ${esc(v.action||'Not selected')}. Correct: Plug an Ethernet cable into the user workstation.</p><p><b>Explanation:</b> Packet loss interrupts real-time voice streams; a wired connection can isolate wireless interference and instability. <b>Remember Tip:</b> Voice traffic is especially sensitive to jitter, delay and packet loss.</p></div>`:''}</section>`}
function voipPart(n){if(exam.paused)return;voip350State().part=n;renderExam()}
function voipTab(t){if(exam.paused)return;voip350State().tab=t;renderExam()}
function voipSelect(k,v){if(exam.paused)return;let s=voip350State();s[k]=v;s.submitted=false}
function voipReset(){if(exam.paused)return;exam.voip350=null;renderExam()}
function voipSubmit(){if(exam.paused)return;voip350State().submitted=true;renderExam()}
function voipCommand(e){
e.preventDefault();if(exam.paused)return;
const v=voip350State(),el=document.getElementById('voip-input');
const entered=el.value.trim(),cmd=entered.toLowerCase();if(!cmd)return;
const a=v.tab.startsWith('Site A'),voip=v.tab.endsWith('VoIP');
const host=a?'192.168.10.24':'192.168.20.24',gateway=a?'192.168.10.1':'192.168.20.1',server='203.0.113.20';
const site=a?'SiteA':'SiteB';let response='';
if(cmd==='help')response='Supported commands:\n  ipconfig /all     Display IPv4 configuration and default gateway\n  ping <address>    Test reachability and packet loss\n  pathping <address> Check loss along a network path\n  tracert <address>  Display network hops\n  status            Display workstation or VoIP status\n  cls               Clear the terminal\n\nStart with ipconfig /all. Addresses are simulated practice values.';
else if(cmd==='cls'||cmd==='clear'){v.logs[v.part+'|'+v.tab]='';renderExam();return}
else if(cmd==='ipconfig'||cmd==='ipconfig /all')response='Windows IP Configuration\n\n   Host Name . . . . . . . . . . . : '+site+'-PC\n   DHCP Enabled . . . . . . . . . : Yes\n\n'+(a?'Wireless LAN adapter Wi-Fi:':'Ethernet adapter Ethernet:')+'\n\n   Media State . . . . . . . . . : Media connected\n   Description . . . . . . . . . : '+(a?'Wireless Network Adapter':'Ethernet Network Adapter')+'\n   DHCP Enabled . . . . . . . . . : Yes\n   IPv4 Address. . . . . . . . . : '+host+'(Preferred)\n   Subnet Mask . . . . . . . . . : 255.255.255.0\n   Default Gateway . . . . . . . : '+gateway+'\n   DNS Servers . . . . . . . . . : '+gateway+'\n\nPractice data only; not sourced from the exam PDF.';
else if(cmd==='status')response=voip?(a?'Site A VoIP: dropped calls reported; high packet loss.':'Site B VoIP: calls stable; no packet loss observed.'):(a?'Site A: wireless workstation; intermittent link.':'Site B: wired workstation; stable link.');
else if(/^(ping|pathping|tracert)(\s+.*)?$/.test(cmd)){
const parts=cmd.split(/\s+/),op=parts[0],target=parts.slice(1).join(' ');
if(!target)response='Usage: '+op+' <IP address>\nFirst run ipconfig /all to find the Default Gateway.';
else if(!/^\d{1,3}(\.\d{1,3}){3}$/.test(target))response='Ping request could not find host '+target+'. Check the name and try again.';
else if(op==='ping'){
const lost=a?2:0;response='Pinging '+target+' with 32 bytes of data:\n'+Array.from({length:4},(_,i)=>a&&i>=2?'Request timed out.':'Reply from '+target+': bytes=32 time='+(a?i*8+12:i+2)+'ms TTL=64').join('\n')+'\n\nPing statistics for '+target+':\n    Packets: Sent = 4, Received = '+(4-lost)+', Lost = '+lost+' ('+(lost*25)+'% loss)\nApproximate round trip times in milli-seconds:\n    Minimum = 2ms, Maximum = '+(a?20:5)+'ms, Average = '+(a?16:3)+'ms';}
else if(op==='pathping')response='Tracing route to '+target+' over a maximum of 30 hops:\n  0  '+site+'-PC ['+host+']\n  1  '+gateway+'\n  2  '+target+'\n\nComputing statistics (simulated)...\n  Source to Here  Lost/Sent = '+(a?'3/10 = 30%':'0/10 = 0%')+'\n'+(a?'Packet loss observed on Site A connection.':'No significant packet loss observed on Site B.');
else response='Tracing route to '+target+' over a maximum of 30 hops\n  1     2 ms     3 ms     2 ms  '+gateway+'\n  2    14 ms    15 ms    14 ms  '+target+'\nTrace complete.\nNote: tracert shows route and delay, not reliable packet-loss statistics.';
}else response="'"+entered.split(/\s+/)[0]+"' is not recognized as an internal or external command.\nType help for supported practice commands.";
const k=v.part+'|'+v.tab;
v.logs[k]=(v.logs[k]||'')+'C:\\Users\\'+site+'> '+entered+'\n'+response+'\n\n';renderExam();
}


/* Question 340: original two-stage SOHO starter-kit PBQ. */
function q340State(){exam.q340??={part:1,connectors:Array(6).fill(''),tools:Array(6).fill(''),ports:Array(8).fill(''),submitted:false};return exam.q340}
function q340Set(group,i,value){if(exam.paused)return;const st=q340State();st[group][i]=value;st.submitted=false;renderExam()}
function q340Part(n){if(exam.paused)return;q340State().part=n;renderExam()}
function q340Reset(){if(exam.paused)return;let st=q340State();if(st.part===1){st.connectors.fill('');st.tools.fill('')}else st.ports.fill('');st.submitted=false;renderExam()}
function q340Icon(o){const original={'Cable Stripper':'telephone_crimper','Cable Crimpers':'ethernet_crimper'}[o];return 'assets/q340_icon_'+(original||o.toLowerCase().replace(/[^a-z0-9]+/g,'_'))+'.png'}
function q340Pick(group,i,options){
 const mirrored = group==='connectors' ? i%2===1 : group==='ports' ? [1,2,3,5,7].includes(i) : false;
 const value=q340State()[group][i], id='q340-'+group+'-'+i;
 const icon=v=>v==='No connection'?'<span class="q340-none">∅</span>':`<img src="${q340Icon(v)}" alt="">`;
 return `<div class="q340-imagepicker ${mirrored?'q340-mirror':''}"><button type="button" class="q340-img-trigger" aria-label="Choose ${group} for position ${i+1}" aria-expanded="false" onclick="q340Toggle('${id}')" ${exam.paused?'disabled':''}>${value?icon(value):'<span class="q340-plus">+</span>'}${value?`<span class="q340-choice-label">${esc(value)}</span>`:''}</button><div id="${id}" class="q340-img-menu" hidden>${options.map(o=>`<button type="button" aria-label="${esc(o)}" title="${esc(o)}" onclick="q340Set('${group}',${i},'${o}')">${icon(o)}<span class="q340-option-label">${esc(o)}</span></button>`).join('')}<button type="button" title="Clear selection" aria-label="Clear selection" onclick="q340Set('${group}',${i},'')">× Clear</button></div></div>`;
}
function q340Toggle(id){const menu=document.getElementById(id);if(!menu)return;const opening=menu.hidden;document.querySelectorAll('.q340-img-menu').forEach(m=>m.hidden=true);menu.hidden=!opening}
function q340HTML(){
 const st=q340State(),c=['RJ11','RJ45','F Connector'],tools=['Cable Stripper','Cable Crimpers','Punchdown tool'],ends=['RJ11','RJ45','F Connector','No connection'];
 let content='';
 if(st.part===1){
  const ys=[[21.8,33.4],[49.0,61.0],[79.0,90.0]];
  let overlay='';
  ys.forEach((pair,r)=>{[0,1].forEach(side=>{const x=side?89.2:32.0,idx=r*2+side;overlay+=`<div class="q340-overlay q340-connector-slot" style="left:${x}%;top:${pair[0]}%">${q340Pick('connectors',idx,c)}</div><div class="q340-overlay q340-tool-slot" style="left:${x}%;top:${pair[1]}%">${q340Pick('tools',idx,tools)}</div>`})});
  content=`<p><b>Step 1:</b> Choose the connector images (blue slots) and tool images (yellow slots) directly on the original PDF diagram. Both ends of every cable need selections.</p><div class="q340-diagram"><img src="assets/q340_step1_diagram.png" alt="Original PDF Step 1 cable connector and tool diagram">${overlay}</div>`;
 }else{
  const locations=[[13.5,81.0],[25.3,84.0],[37.3,84.0],[48.5,84.0],[40.3,69.5],[60.3,63.5],[60.3,89.0],[75.8,74.0]];
  let overlay=locations.map(([x,y],i)=>`<div class="q340-overlay q340-port" style="left:${x}%;top:${y}%">${q340Pick('ports',i,ends)}</div>`).join('');
  content=`<p><b>Step 2:</b> Choose connector-end images (not complete cables) on the original PDF device diagram. Match the wall outlet, router, telephone, modem, and PC.</p><div class="q340-diagram"><img src="assets/q340_step2_diagram.png" alt="Original PDF Step 2 SOHO connection diagram">${overlay}</div>`;
 }
 const keyC=['RJ11','RJ11','F Connector','F Connector','RJ45','RJ45'];
 const keyT=['Cable Stripper','Cable Stripper','Cable Crimpers','Cable Crimpers','Cable Stripper','Cable Stripper'];
 // Answer placements follow the marked reference diagram, including its nonstandard device icons.
 const keyP=['F Connector','RJ11','RJ45','RJ45','RJ11','RJ45','F Connector','RJ45'];
 const entries=[...keyC.map((v,i)=>({label:`Step 1 · ${['Top','Middle','Bottom'][Math.floor(i/2)]} cable · ${i%2?'right':'left'} connector`,got:st.connectors[i],key:v})),...keyT.map((v,i)=>({label:`Step 1 · ${['Top','Middle','Bottom'][Math.floor(i/2)]} cable · ${i%2?'right':'left'} tool`,got:st.tools[i],key:v})),...keyP.map((v,i)=>({label:`Step 2 · ${['Wall outlet','Router phone','Router LAN','Router WAN','Telephone','Modem upper','Modem lower','PC'][i]}`,got:st.ports[i],key:v}))];
 const correct=entries.filter(e=>e.got===e.key).length;
 const review=st.submitted?`<div class="review"><b>PBQ Review — ${correct}/${entries.length} correct (Step 1: ${entries.slice(0,12).filter(e=>e.got===e.key).length}/12; Step 2: ${entries.slice(12).filter(e=>e.got===e.key).length}/8)</b>${entries.map(e=>`<p style="margin:7px 0;color:${e.got===e.key?'#087b35':'#b42318'}"><b>${e.got===e.key?'Correct':'Incorrect'} — ${esc(e.label)}</b><br>Your selection: ${esc(e.got||'Not selected')} | Correct: ${esc(e.key)}</p>`).join('')}<div class="q340-teaching"><h3>Explanation — Step 1</h3><ul><li><b>Top telephone cable — RJ11 + Cable Stripper (both ends):</b> The four colored conductors are used for the telephone connection, so the smaller RJ11 connector matches this cable. The Cable Stripper removes the outer jacket to expose the individual colored wires for preparing each end. The outer jacket must be opened at each cable end to reach the conductors without cutting through them.</li><li><b>Middle coaxial cable — F Connector + Cable Crimpers (both ends):</b> The coaxial cable has a central conductor surrounded by insulation and shielding. The F Connector is shaped for this coaxial construction and connects it to the threaded coax ports. Cable Crimpers are selected to secure the connector to the prepared cable end, helping keep the connection firmly attached.</li><li><b>Bottom twisted-pair cable — RJ45 + Cable Stripper (both ends):</b> The multiple color-coded pairs carry the wired network connection, so RJ45 is the matching modular connector. The Cable Stripper removes the black outer jacket so the colored pairs can be exposed and organized. Each end has its own jacket covering the pairs, so each end must be stripped to reach and arrange its conductors.</li></ul><h3>Explanation — Step 2</h3><ul><li><b>Wall ISP service outlet — F Connector:</b> This is the coaxial service entry point, so the threaded coax connector matches.</li><li><b>Router phone service — RJ11:</b> The telephone service jack uses the smaller voice connector.</li><li><b>Router LAN 1–4 — RJ45:</b> These network ports connect local wired devices.</li><li><b>Router WAN — RJ45:</b> The WAN port receives the network link from the modem.</li><li><b>Telephone — RJ11:</b> Its voice line uses the telephone connector.</li><li><b>Modem upper — RJ45:</b> This Ethernet-side port links the modem to the router.</li><li><b>Modem lower — F Connector:</b> This coaxial input receives the cable service feed.</li><li><b>Home PC — RJ45:</b> The PC network port connects to the router through an Ethernet cable.</li></ul><h3>Why the other pictured choices do not match</h3><ul><li><b>RJ11 versus RJ45:</b> The smaller RJ11 fits the telephone line; RJ45 fits the larger network jacks.</li><li><b>F Connector:</b> The coax connector fits the round cable service connection, not the rectangular phone or network ports.</li><li><b>Cable Stripper:</b> Its cutting edge opens the outer jacket while leaving the inner colored conductors available for termination.</li><li><b>Cable Crimpers:</b> Its jaws press a compatible connector firmly onto a prepared cable end, helping prevent a loose mechanical connection.</li><li><b>Punchdown tool:</b> Seats individual wires into terminal slots; those terminals are not the connector ends shown here.</li></ul><h3>Remember Tips</h3><ul><li><b>Read the cable structure first:</b> A few straight conductors point to the telephone cable; a central conductor with shielding points to coax; multiple twisted pairs point to the network cable.</li><li><b>Strip = expose:</b> The jacket comes off so you can work with the colored conductors.</li><li><b>Crimp = secure:</b> The connector is mechanically fastened to the prepared cable.</li><li><b>Punchdown = seat:</b> A punchdown tool presses individual conductors into insulation-displacement contacts on a jack or patch panel; it does not attach a plug to a loose cable end.</li><li><b>Trace the service:</b> Coax enters the modem, Ethernet links modem to router and PC, and RJ11 carries the telephone connection.</li></ul></div></div>`:'';
 return `<section class="q340"><h2>Question 340 — SOHO Starter Kit <small style="font-size:12px;color:#1674a5">Detailed grading and teaching v12</small></h2><p>Connect the computer for internet access and the telephone for a dial tone.</p><div class="q341-tabs"><button class="${st.part===1?'active':''}" onclick="q340Part(1)">Step 1 — Cable Connectors &amp; Tools</button><button class="${st.part===2?'active':''}" onclick="q340Part(2)">Step 2 — Connect Outlets &amp; Devices</button></div>${content}<div class="actions"><button class="secondary" onclick="q340Reset()" ${exam.paused?'disabled':''}>Reset Step ${st.part}</button><button class="primary" onclick="q340State().submitted=true;renderExam()" ${exam.paused?'disabled':''}>Submit Answers</button></div>${review}</section>`;
}

/* Question 341: two independent, interactive simulation stages. */
function q341State(){exam.q341??={part:1,connectors:['','',''],tools:['','',''],ends:['','','',''],submitted:false};return exam.q341}
function q341Set(kind,i,value){if(exam.paused)return;let v=q341State();v[kind][i]=value;v.submitted=false;renderExam()}
function q341Part(n){if(exam.paused)return;q341State().part=n;renderExam()}
function q341Reset(){if(exam.paused)return;let n=q341State().part;let v=q341State();if(n===1){v.connectors=['','',''];v.tools=['','','']}else v.ends=['','','',''];v.submitted=false;renderExam()}
function q341Pick(kind,i){if(exam.paused)return;let st=q341State();st.picker=(st.picker&&st.picker.kind===kind&&st.picker.i===i)?null:{kind,i};renderExam()}
function q341Choose(value){let st=q341State(),p=st.picker;if(!p)return;st[p.kind][p.i]=value;st.picker=null;st.submitted=false;renderExam()}
function q341Icon(name){let file={'LC':'LC','RJ11':'RJ11','RJ45':'RJ45','Crimper':'Crimper','Optical Crimper':'Optical_Crimper','Punchdown':'Punchdown','RJ11 cable end':'step1_copper_terminated','RJ45 cable end':'step1_twisted_terminated','LC fiber connector':'step1_fiber_terminated','Unterminated DSL cable':'step1_copper_bare','Unterminated twisted-pair cable':'step1_twisted_bare','Unterminated fiber cable':'step1_fiber_bare'}[name];return file?`<img src="assets/q341_${file}.png" alt="${esc(name)}">`:''}
function q341Slot(kind,i,x,y){let st=q341State(),value=st[kind][i],active=st.picker&&st.picker.kind===kind&&st.picker.i===i;return `<button class="q341-overlay ${active?'selected':''}" style="left:${x}%;top:${y}%" onclick="q341Pick('${kind}',${i})" aria-label="Choose ${kind} ${i+1}">${value?q341Icon(value):'<b>+</b>'}</button>`}
function q341Picker(){let st=q341State(),pk=st.picker;if(!pk)return '';let opts=pk.kind==='connectors'?['LC','RJ11','RJ45']:pk.kind==='tools'?['Crimper','Optical Crimper','Punchdown']:['Unterminated DSL cable','RJ11 cable end','Unterminated twisted-pair cable','RJ45 cable end','Unterminated fiber cable','LC fiber connector'];return `<div class="q341-picker"><div class="q341-picker-head">Choose a cable end from the Step 1 diagram <button class="secondary" onclick="q341Pick('${pk.kind}',${pk.i})">Close</button></div><div class="q341-options">${opts.map(o=>`<button title="${esc(o)}" aria-label="${esc(o)}" onclick="q341Choose('${o}')">${q341Icon(o)}<span class="q341-option-label">${esc(o)}</span></button>`).join('')}<button title="Clear selection" onclick="q341Choose('')">✕</button></div></div>`}
function q341HTML(){
 let v=q341State();
 const key={connectors:['RJ11','LC','RJ45'],tools:['Crimper','Optical Crimper','Crimper'],ends:['RJ45 cable end','Unterminated twisted-pair cable','RJ45 cable end','RJ45 cable end']};
 let labels={connectors:['Top telephone/DSL connector','Middle fiber connector','Bottom twisted-pair connector'],tools:['Top cable tool','Middle fiber tool','Bottom telephone tool'],ends:['Patch panel front','Patch panel rear','Switch','Wireless access point']};
 let groups=['connectors','tools','ends'],count=0,total=10;
 let rows=groups.flatMap(g=>key[g].map((correct,i)=>{let chosen=v[g][i],ok=chosen===correct;if(ok)count++;return `<div class="q341-result ${ok?'q341-ok':'q341-bad'}"><b>${ok?'Correct':'Incorrect'} — ${labels[g][i]}</b><div class="q341-compare"><span>Your selection: ${chosen?q341Icon(chosen):'Not selected'} ${esc(chosen||'None')}</span><span>Correct: ${q341Icon(correct)} ${esc(correct)}</span></div></div>`}));
 return `<section class="q341"><h2>Question 341 — Cabling and Access Point Connections</h2><p>Complete both parts using the original diagrams. Selections are saved when switching between parts.</p><div class="q341-tabs"><button class="${v.part===1?'active':''}" onclick="q341Part(1)">Part 1 — Connectors &amp; Tools</button><button class="${v.part===2?'active':''}" onclick="q341Part(2)">Part 2 — Match Cable Ends to Network Devices</button></div>${v.part===1?`<p><b>Part 1:</b> Select the connector picture at the left and the matching tool picture at the right of each cable.</p><div class="q341-stage"><img src="assets/question341_reference_1.png" alt="Original three-cable connector and tool diagram">${[0,1,2].map(i=>q341Slot('connectors',i,12.2,28.5+i*25)+q341Slot('tools',i,88,28.5+i*25)).join('')}</div>`:`<p><b>Part 2:</b> Use the same three cable types shown in Part 1. Select the original cable end (bare or terminated) for the patch panel front, patch panel rear, switch, and access point. The six choices reuse the Step 1 wire illustrations.</p><div class="q341-stage"><img src="assets/question341_reference_3.png" alt="Original network device diagram">${[[11,22],[89,22],[11,73],[89,73]].map(([x,y],i)=>q341Slot('ends',i,x,y)).join('')}</div>`}${q341Picker()}<div class="actions"><button class="secondary" onclick="q341Reset()">Reset Part ${v.part}</button><button class="primary" onclick="q341State().submitted=true;renderExam()">Submit Answers</button></div>${v.submitted?`<div class="review"><b>PBQ Review — ${count}/${total} correct</b><p>Your selections compared with the answer image:</p>${rows.join('')}<div class="q341-teaching"><h3>Part 1 — Why these connections actually work</h3><ul><li><b>Telephone/DSL cable → RJ11 + Crimper:</b> The gray cable has the smaller telephone-style conductor arrangement. RJ11 fits the telephone jack and makes electrical contact with those conductors. The crimper pushes the metal contacts through the wire insulation and locks the plug onto the cable. A loose RJ11 plug can cause a dead dial tone or intermittent DSL service. An RJ45 plug is physically wider and is meant for a different port.</li><li><b>Fiber cable → LC + Optical Crimper (the pictured tool choice):</b> The light-blue cable contains optical fibers that carry pulses of light, not electrical current. An LC connector precisely aligns the fiber end with the optical port; poor alignment or a dirty end face can cause high light loss and dropped links. The simulation pairs this cable with its pictured optical crimper. In actual field installations, LC termination often uses specialized cleaving, polishing, or fusion-splicing tools depending on the connector system; a normal copper-wire crimper will not do the job.</li><li><b>Twisted-pair network cable → RJ45 + Crimper:</b> The black jacket exposes four twisted pairs, eight conductors total. An RJ45 (8P8C) plug provides eight contacts for those conductors. The crimper seats the contacts and clamps the strain relief. The pair order matters: a poor termination can cause a link to negotiate at a lower speed or fail altogether. LC cannot work because these are copper conductors, not optical fibers.</li></ul><h3>Part 2 — Why the cable ends change at each device</h3><ul><li><b>Patch panel FRONT → RJ45 cable end:</b> The front is a row of sockets. It is designed for removable patch cords with RJ45 plugs, so a terminated black twisted-pair cable belongs here.</li><li><b>Patch panel REAR → Unterminated twisted-pair cable:</b> The rear has IDC punch-down contacts. Bare insulated conductors are seated individually with a punch-down tool; an RJ45 plug would have nowhere to snap in. This is the permanent building-cable side, not the patch-cord side.</li><li><b>Switch → RJ45 cable end:</b> The switch presents RJ45 sockets. A finished plug mates with the contacts; loose pairs cannot be inserted reliably and must not be treated as a finished cable.</li><li><b>Access point → RJ45 cable end:</b> Its network uplink accepts the same terminated twisted-pair cable. Many access points can also receive Power over Ethernet through that connection, so a sound termination matters for both connectivity and power.</li></ul><h3>Remember Tips — Diagnose it like a technician</h3><ul><li><b>Loose plug, unstable link?</b> Check that the crimped contacts are seated and the jacket is held by the strain relief; tugging on bare conductors is a warning sign.</li><li><b>Patch panel puzzle?</b> Think <i>front = patch cord you can unplug</i>; <i>rear = fixed building cable punched into IDC terminals</i>. The two faces do different jobs.</li><li><b>Fiber link not coming up?</b> Verify LC connector fit and clean optical end faces before blaming the switch. Copper plugs cannot substitute for an optical connector.</li><li><b>RJ45 link stuck at 100 Mb/s?</b> Inspect all four pairs and the termination: Gigabit copper Ethernet needs all four pairs correctly connected.</li><li><b>Tool decision:</b> A crimper attaches a modular plug; a punch-down tool seats individual wires into IDC slots. Pick the tool based on the termination point, not just the cable color.</li></ul></div></div>`:''}</section>`;
}
const q342Options=[['2TB SATA SSD','2TB · SATA · SSD'],['1TB SAS 10k rpm','1TB · SAS · 10k rpm'],['4TB SAS 10k rpm','4TB · SAS · 10k rpm'],['4TB SATA SSD','4TB · SATA · SSD'],['4TB SATA 7200rpm','4TB · SATA · 7200rpm'],['8TB SAS 5400rpm','8TB · SAS · 5400rpm'],['4TB SAS 15k rpm','4TB · SAS · 15k rpm']];
const q342Key={s1b2:'4TB SAS 15k rpm',s2b5:'2TB SATA SSD'};
function q342State(){exam.q342??={values:{},submitted:false};return exam.q342}
function q342Set(k,v){let st=q342State();st.values[k]=v;st.submitted=false;renderExam()}
function q342Reset(){exam.q342={values:{},submitted:false};renderExam()}
function q342Inspect(server,tab){let st=q342State();st.inspectServer=server;st.inspectTab=tab;renderExam()}

function q342HTML(){
 const st=q342State(),bays=[2,3,4,5],allKeys=[...bays.map(b=>'s1b'+b),...bays.map(b=>'s2b'+b)];
 const expected=k=>q342Key[k]||'';
 const isCorrect=k=>(st.values[k]||'')===expected(k);
 const count=allKeys.filter(isCorrect).length;
 const names={s1b2:'Server 1 — bay 2 (predicted failure)',s1b3:'Server 1 — bay 3',s1b4:'Server 1 — bay 4',s1b5:'Server 1 — bay 5',s2b2:'Server 2 — bay 2',s2b3:'Server 2 — bay 3',s2b4:'Server 2 — bay 4',s2b5:'Server 2 — bay 5 (failed/offline)'};
 const diskSpecs={s1b2:['4TB','HDD','15k rpm','Online','Yes'],s1b3:['4TB','HDD','15k rpm','Online','No'],s1b4:['4TB','HDD','15k rpm','Online','No'],s1b5:['4TB','HDD','15k rpm','Online','No'],s2b2:['2TB','HDD','7200rpm','Online','No'],s2b3:['8TB','HDD','5400rpm','Online','No'],s2b4:['2TB','SSD','—','Online','No'],s2b5:['2TB','HDD','7200rpm','Offline','Failed']};
 const statusTable=server=>`<div class="q342-status-window"><div class="q342-status-header"><strong>Server ${server} — Physical Disk Status</strong></div><div class="q342-status-body"><p class="q342-table-note">Original disk specifications remain visible. State and Failure predicted update immediately for every selection. A correct replacement clears the warning in this practice simulation; an incorrect replacement displays Yes for a predicted risk or Failed for an originally failed disk until a suitable drive is selected. Submit Answers grades all eight bays.</p><table aria-label="Server ${server} physical disk status"><thead><tr><th>Status</th><th>Name</th><th>State</th><th>Size</th><th>Media</th><th>Speed</th><th>Failure predicted</th><th>Original state / warning</th><th>Your selected action</th>${st.submitted?'<th>Grade</th>':''}</tr></thead><tbody>${bays.map(b=>{const k='s'+server+'b'+b;const failed=k==='s2b5',predicted=k==='s1b2';const selected=st.values[k]||'';const [size,media,speed,state,warning]=diskSpecs[k];const label=selected?(q342Options.find(x=>x[0]===selected)?.[1]||selected):'Keep installed drive';const liveState=!selected?state:(isCorrect(k)?'Online':'Needs review');const liveWarning=!selected?warning:(isCorrect(k)?'No':(warning==='Failed'?'Failed':'Yes'));return `<tr><td><span class="${liveState==='Online (simulated)'||liveState==='Online'?'q342-good':'q342-bad'}">${liveState==='Online (simulated)'||liveState==='Online'?'✔':'✖'}</span></td><td>Physical disk ${server}:${b}</td><td>${liveState}</td><td>${size}</td><td>${media}</td><td>${speed}</td><td>${liveWarning}</td><td>${state} / ${warning}</td><td><strong>${esc(label)}</strong></td>${st.submitted?`<td><strong class="${isCorrect(k)?'q342-good':'q342-bad'}">${isCorrect(k)?'✓ Correct':'✕ Incorrect'}</strong></td>`:''}</tr>`}).join('')}</tbody></table></div></div>`;
 const row=server=>`<div class="q342-grid">${bays.map(b=>{const k='s'+server+'b'+b,v=st.values[k]||'',bad=st.submitted&&!isCorrect(k);const [size,media,speed,state,warning]=diskSpecs[k];return `<div class="q342-bay ${st.submitted?(bad?'q342-wrong':'q342-right'):''}"><div class="q342-baytitle">Server ${server} — Drive bay ${b}</div><div class="q342-drive">💽 <b>${size} ${media} · ${speed}</b> · ${warning==='Yes'?'Predicted failure':warning==='Failed'?'Offline / failed':'Online'}</div><label>Action / replacement drive<select onchange="q342Set('${k}',this.value)"><option value="">Keep installed drive</option>${q342Options.map(([id,label])=>`<option value="${id}" ${v===id?'selected':''}>${label}</option>`).join('')}</select></label>${st.submitted?`<p><b class="${isCorrect(k)?'q342-good':'q342-bad'}">${isCorrect(k)?'✓ Correct':'✕ Incorrect'}</b>${v&&!isCorrect(k)?'<br><small>Drive does not match this bay; review capacity, interface, and speed.</small>':''}</p>`:''}</div>`}).join('')}</div>`;
 return `<section class="q342" id="question342"><h2>Question 342 — Server disk repair (RAID-5)</h2><p>Inspect the RAID and physical-disk status below. Select a replacement for any disk requiring repair; leave healthy bays unchanged. Then select Submit Answers to compare every bay against the reference.</p><p class="muted">Every drive choice is shown immediately in its blue status table, including incorrect choices. The original disk specifications remain unchanged for comparison. Submit Answers grades every bay.</p><details><summary>View original PDF server status screenshots</summary><img class="q342-overview" src="assets/q342_overview.png" alt="Original RAID overview"><img class="q342-overview" src="assets/q342_disk_status.png" alt="Original physical disk reports"></details><h3>Server 1 — Drive bays 2–5</h3><img class="q342-overview" src="assets/q342_server1.png" alt="Original Server 1 drive replacement choices">${statusTable(1)}${row(1)}<h3>Server 2 — Drive bays 2–5</h3><img class="q342-overview" src="assets/q342_server2.png" alt="Original Server 2 drive replacement choices">${statusTable(2)}${row(2)}<div class="actions"><button class="secondary" onclick="q342Reset()">Reset PBQ</button><button class="primary" onclick="q342Submit()">Submit Answers</button></div>${st.submitted?`<div class="review" aria-live="polite"><h3>PBQ Review — ${count}/8 drive bays correct</h3><p>Each bay is graded, including healthy bays that should remain unchanged.</p>${allKeys.map(k=>`<p><b class="${isCorrect(k)?'q342-good':'q342-bad'}">${isCorrect(k)?'✓ Correct':'✕ Incorrect'} — ${names[k]}</b><br>Your selection: ${esc(st.values[k]||'Keep installed drive')}<br>Correct selection: ${esc(expected(k)||'Keep installed drive')}</p>`).join('')}<h4>Explanation — Why these exact drives matter</h4><p><b>Server 1, bay 2 — 4TB SAS 15K RPM:</b> The disk is still online, but its predictive-failure warning means it may stop responding soon. The 4TB capacity matters because a replacement smaller than the array member may not hold the required data and parity layout, preventing a rebuild. SAS matters because the drive must connect to the server’s SAS backplane/controller. The 15,000 RPM speed matters because slower spinning disks may become a bottleneck during reads, writes, and the rebuild. Replacing this drive before it fails reduces the chance of an emergency recovery.</p><p><b>Server 2, bay 5 — 2TB SATA SSD:</b> This disk is already offline, leaving RAID-5 degraded. The supplied exercise answer selects a 2TB SATA SSD. Here, 2TB is the required capacity in the reference: a smaller replacement may not provide enough usable space to rebuild the missing member. SATA specifies the interface; SSD has no spinning platter and can deliver faster random access than a mechanical drive. <b>Important:</b> A SATA SSD is not automatically interchangeable with a SAS HDD. In real servers, verify the backplane, controller, array configuration, and supported drive list before installing it; the 2TB SATA SSD is the reference answer for this simulation, not a universal replacement rule.</p><h4>Correct versus incorrect choices</h4><p><b>Server 1:</b> A 1TB SAS drive is too small; a 4TB SAS 10K RPM drive matches capacity and interface but has a lower spindle speed than the reference 15K RPM drive. A 4TB SATA drive changes the interface. An 8TB SAS 5400 RPM drive adds capacity but runs much more slowly and is not the specified match. Choosing a healthy bay risks disrupting a working array member.</p><p><b>Server 2:</b> The reference requires the 2TB SATA SSD for the offline bay 5. A 1TB replacement offers less capacity; SAS HDD choices use a different interface and performance profile; 4TB SATA alternatives have different capacity or drive technology. Larger is not automatically better, and the correct choice depends on controller support and the existing array. Bays 2–4 remain online: do not replace them.</p><h4>Remember Tips — Think like a server technician</h4><p><b>Capacity is a rebuild requirement:</b> RAID cannot simply squeeze a 4TB member’s required layout onto a 1TB disk. Check the actual usable size, not just the number printed on the label.</p><p><b>Interface is a compatibility gate:</b> SAS and SATA are not interchangeable in every backplane. Check the controller and slot before ordering a drive.</p><p><b>Speed affects the whole array:</b> During a RAID-5 rebuild, surviving disks are read heavily while parity reconstructs missing data. A slower replacement can prolong degraded operation.</p><p><b>Warning versus failure:</b> Predictive failure means plan a controlled replacement; offline means act promptly and confirm backups. RAID-5 can survive one failed member, but another failure before the rebuild completes can cause data loss.</p></div>`:''}</section>`;
}
function q342Submit(){q342State().submitted=true;exam.revealed[342]=true;renderExam()}

const q351Items=['TONER','FUSER','DUPLEXER','INK CARTRIDGE','ROLLERS'];
const q351Slots=['Upper printer area','Printer body','Tray 2 — Letter','Tray 3 — Legal'];
const q351Key=['','TONER','','ROLLERS'];
function q351State(){exam.q351??={slots:['','','',''],selected:'',submitted:false};return exam.q351}
function q351Choose(v){if(exam.paused)return;let st=q351State();st.selected=v;renderExam()}
function q351Place(i,v){if(exam.paused)return;let st=q351State();v=v||st.selected;if(!v)return;st.slots=st.slots.map(x=>x===v?'':x);st.slots[i]=v;st.selected='';st.submitted=false;renderExam()}
