function q351HTML(){let st=q351State(),correct=st.slots.map((v,i)=>v===q351Key[i]);return `<section class="q351"><h2>Question 351 — Office printer troubleshooting</h2><p>Use the original printer image. Drag a component image into the matching yellow position, or select an image and then a position. Leave positions without a faulty component empty. Each part can be used only once.</p><div class="q351-stage"><img class="q351-background" src="assets/q351_printer_original.png" alt="Original printer diagram showing four yellow response boxes and five component images" />${q351Slots.map((label,i)=>`<div class="q351-slot q351-slot-${i} ${st.submitted?(correct[i]?'q351-right':'q351-wrong'):''}" role="button" tabindex="0" title="${label}" aria-label="${label}" ondragover="event.preventDefault()" ondrop="event.preventDefault();q351Place(${i},event.dataTransfer.getData('text/plain'))" onclick="q351Place(${i})" onkeydown="if(event.key==='Enter')q351Place(${i})">${st.slots[i]?`<img src="assets/q351_${st.slots[i].toLowerCase().replaceAll(' ','_')}.png" alt="${st.slots[i]}" />`: '<span>+</span>'}</div>`).join('')}</div><div class="q351-palette"><strong>Drag &amp; Drop — original component images</strong><div class="q351-items">${q351Items.map(v=>`<button class="q351-token ${st.selected===v?'q351-picked':''}" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${v}')" onclick="q351Choose('${v}')" aria-label="Select ${v}"><img src="assets/q351_${v.toLowerCase().replaceAll(' ','_')}.png" alt="${v}" /></button>`).join('')}</div></div><div class="actions"><button class="secondary" onclick="q351Reset()">Reset All</button><button class="primary" onclick="q351State().submitted=true;renderExam()">Submit Answers</button></div>${st.submitted?`<div class="review"><b>PBQ Review — ${correct.filter(Boolean).length}/4 positions correct</b>${q351Slots.map((label,i)=>`<p>${correct[i]?'✓ Correct':'✕ Incorrect'} — ${label}: Your selection: ${st.slots[i]||'Empty'}; Correct: ${q351Key[i]||'Leave empty'}</p>`).join('')}<h3>Why each placement matters</h3><p><b>Printer body — TONER:</b> A laser printer transfers powdered toner onto a page to create letters and graphics. The cartridge sits inside the main printer housing, where the imaging system can deliver toner to the drum. If pages come out faint or streaked, check toner level and cartridge condition before replacing paper-feed parts.</p><p><b>Tray 3 (Legal) — ROLLERS:</b> Pickup rollers use friction to pull one sheet from the tray into the paper path. Legal paper is longer than letter paper, so slipping or dirty rollers may cause misfeeds, skewed pages, or jams near the tray. Clean the rollers and inspect for wear; replace them when they cannot grip paper reliably.</p><p><b>Upper position — Leave empty:</b> No replacement is indicated here. A fuser uses heat and pressure to bond toner to the page after transfer; investigate it when toner rubs off, smears, or does not adhere, rather than treating every print problem as a fuser failure.</p><p><b>Tray 2 (Letter) — Leave empty:</b> A working letter-paper tray needs no part swap. A duplexer reverses or redirects paper for printing on both sides; suspect it when jams happen specifically during double-sided printing, not during ordinary pickup from a tray.</p><h3>Why the unused components do not fit</h3><p><b>FUSER:</b> Repairs toner-bonding problems, not weak pickup from the legal tray. <b>DUPLEXER:</b> Handles two-sided paper routing, not the initial feed. <b>INK CARTRIDGE:</b> Holds liquid ink for inkjet printing; a laser printer uses dry toner instead.</p><h3>Remember Tips</h3><ul><li><b>Blank or faded page:</b> Check the toner cartridge and imaging path first.</li><li><b>Toner wipes off the page:</b> Investigate fuser temperature and pressure.</li><li><b>Paper stops near a tray:</b> Inspect pickup rollers, paper guides, and paper condition.</li><li><b>Only double-sided jobs jam:</b> Inspect the duplex paper path.</li><li><b>Laser versus inkjet:</b> Laser printers fuse dry toner; inkjets spray liquid ink through nozzles.</li></ul></div>`:''}</section>`}


function q347State(){exam.q347 ||= {tab:'setup',enabled:false,ssid:'default',channel:'11',hide:false,gonly:false,security:'Open',pass:'',confirm:'',filter:false,filterMode:'Disallow',mac1:false,mac2:false,admin:'',verify:'',submitted:false};return exam.q347}
function q347Set(k,val){q347State()[k]=val;q347State().submitted=false;renderExam()}
function q347Tab(t){q347State().tab=t;renderExam()}
function q347HTML(){
 const v=q347State(),sel=(key,values)=>`<select onchange="q347Set('${key}',this.value)">${values.map(x=>`<option value="${x}" ${v[key]===x?'selected':''}>${x}</option>`).join('')}</select>`,check=(key)=>`<input type="checkbox" ${v[key]?'checked':''} onchange="q347Set('${key}',this.checked)">`,field=(key,type='text')=>`<input type="${type}" value="${esc(v[key])}" oninput="q347State()['${key}']=this.value;q347State().submitted=false">`;
 const checks=[['Wireless enabled',v.enabled,true],['SSID',v.ssid,'HomeWiFi'],['Channel',v.channel,'1'],['SSID broadcast disabled',v.hide,true],['802.11g only',v.gonly,true],['Security mode',v.security,'WPA2'],['Passphrase',v.pass,'CompTIA'],['Confirmed passphrase',v.confirm,'CompTIA'],['MAC filtering enabled',v.filter,true],['MAC filter policy',v.filterMode,'Allow'],['Laptop MAC allowed',v.mac1,true],['Smartphone MAC allowed',v.mac2,true],['Administrator password',v.admin,'Secure$1'],['Verify administrator password',v.verify,'Secure$1']];
 const correct=checks.filter(x=>x[1]===x[2]).length;
 return `<section class="q347"><h2>Question 347 — Laura's Wireless Configuration</h2><p>Configure Laura's home access point using the three tabs. Use the nearby networks to choose a less congested channel, enable the strongest security option shown, and allow only her two devices.</p><div class="q347-neighbors"><img src="assets/q347_reference_2.png" alt="Laura's house and neighboring networks: channel 11, channel 6, channel 11"></div><div class="q347-panel"><div class="q347-header">Laura's Wireless Configuration</div><div class="q347-tabs">${[['setup','WIRELESS SETUP'],['filter','NETWORK FILTER'],['admin','ADMINISTRATOR TOOLS']].map(([id,name])=>`<button class="${v.tab===id?'active':''}" onclick="q347Tab('${id}')">${name}</button>`).join('')}</div><div class="q347-fields">${v.tab==='setup'?`<h3>Wireless Network Settings</h3><label>Enable Wireless ${check('enabled')}</label><label>Wireless Network Name (SSID) ${field('ssid')}</label><label>Wireless Channel ${sel('channel',Array.from({length:11},(_,i)=>String(i+1)))}</label><label>Disable SSID Broadcast ${check('hide')}</label><label>802.11g Only Mode ${check('gonly')}</label><h3>Wireless Security Mode</h3><label>Security Mode <select onchange="q347Set('security',this.value)">${[['Open','Disable Wireless Security (not recommended)'],['WEP','Enable WEP Wireless Security (basic)'],['WPA','Enable WPA Wireless Security (enhanced)'],['WPA2','Enable WPA2 Wireless Security (enhanced)']].map(([value,name])=>`<option value="${value}" ${v.security===value?'selected':''}>${name}</option>`).join('')}</select></label>${v.security!=='Open'?`<label>Passphrase ${field('pass')}</label><label>Confirm Passphrase ${field('confirm')}</label>`:''}`:v.tab==='filter'?`<label>Turn MAC Filtering ON ${check('filter')}</label><div class="q347-filter-select"><select onchange="q347Set('filterMode',this.value)"><option value="Allow" ${v.filterMode==='Allow'?'selected':''}>Allow the following MAC Addresses</option><option value="Disallow" ${v.filterMode==='Disallow'?'selected':''}>Disallow the following MAC Addresses</option></select></div><div class="q347-mac-row"><label>${check('mac1')} <span><strong>Laptop</strong> — 00:0A:BF:03:C4:54</span></label></div><div class="q347-mac-row"><label>${check('mac2')} <span><strong>Smartphone</strong> — 09:2C:D0:22:3F:11</span></label></div>`:`<p>Please enter the same password into both boxes for confirmation.</p><label>Password ${field('admin','password')}</label><label>Verify Password ${field('verify','password')}</label>`}</div></div><div class="actions"><button class="secondary" onclick="delete exam.q347;renderExam()">Reset All</button><button class="primary" onclick="q347State().submitted=true;renderExam()">Submit Answers</button></div>${v.submitted?`<div class="review"><h3>PBQ Review — ${correct}/${checks.length} settings correct</h3>${checks.map(([name,actual,expected])=>`<p class="${actual===expected?'q347-good':'q347-wrong'}"><b>${actual===expected?'Correct':'Incorrect'} — ${name}</b><br>Your setting: ${esc(String(actual))} | Correct: ${esc(String(expected))}</p>`).join('')}<p><b>Explanation:</b> Channel 1 avoids the neighbors using channels 6 and 11 in the provided diagram. WPA2 is the strongest listed encryption mode. MAC allowlisting restricts access to the laptop and smartphone shown, while changing the administrator password protects router management.</p><p><b>Remember Tip:</b> On 2.4 GHz Wi-Fi, channels 1, 6, and 11 are the standard nonoverlapping choices. MAC filtering is an extra access restriction, not a substitute for strong wireless encryption.</p></div>`:''}</section>`;
}

function pbqHTML(q){if(q.id===347)return q347HTML();if(q.id===342)return q342HTML();if(q.id===351)return q351HTML();if(q.id===349)return q349HTML();if(q.id===348)return q348HTML();if(q.id===344)return q344HTML();if(q.id===343)return q343HTML();if(q.id===340)return q340HTML();if(q.id===341)return q341HTML();if(q.id===350)return voip350HTML(q);if(q.id===345)return workstation345HTML(q);if(q.id===346)return printer346HTML(q);let p=exam.placements[q.id]||{};return `<div><b>PBQ — Original PDF visual</b><p class="muted">Review the diagram and instructions as printed. Drag an item into a response slot or tap the item then tap a slot. Use the original diagram to complete the activity. Automated scoring requires a verified key for each response position.</p>${q.image?`<img class="pbqimage" src="${q.image}" alt="Original PDF page ${q.page} for PBQ ${q.id}">`:''}<h2>Interactive PBQ workspace</h2><div id="chips">${(q.options.length?q.options.map(o=>o.key+'. '+o.text):['Choice A','Choice B','Choice C','Choice D']).map((v,i)=>`<span class="chip" draggable="true" data-chip="${i}" ondragstart="dragChip(event,${i})" onclick="chosenChip=${i};document.querySelectorAll('.chip').forEach(c=>c.classList.remove('selected'));this.classList.add('selected')">${esc(v.slice(0,90))}</span>`).join('')}</div>${Array.from({length:Math.min(8,Math.max(4,q.options.length))},(_,i)=>`<div class="dropzone" ondragover="event.preventDefault()" ondrop="dropChip(event,${i})" onclick="placeChip(${i})">Slot ${i+1}: ${p[i]===undefined?'Drop or tap a choice here':esc((q.options.length?q.options.map(o=>o.key+'. '+o.text):['Choice A','Choice B','Choice C','Choice D'])[p[i]]||'')} <button class="secondary" onclick="event.stopPropagation();clearSlot(${i})">Clear</button></div>`).join('')}<button class="secondary" onclick="exam.placements[${q.id}]={};renderExam()">Reset PBQ</button></div>`}
function dragChip(e,i){chosenChip=i;e.dataTransfer.setData('text/plain',String(i))}function dropChip(e,i){e.preventDefault();chosenChip=+e.dataTransfer.getData('text/plain');placeChip(i)}function placeChip(i){if(exam.paused)return;if(chosenChip===null)return;let id=current().id;exam.placements[id]??={};exam.placements[id][i]=chosenChip;chosenChip=null;renderExam()}function clearSlot(i){if(exam.paused)return;delete exam.placements[current().id][i];renderExam()}
function reveal(){if(exam.paused)return;exam.revealed[current().id]=true;renderExam()}
function move(step){if(exam.paused)return;if(step>0&&exam.index===exam.items.length-1){finish(false);return}exam.index=Math.max(0,Math.min(exam.items.length-1,exam.index+step));renderExam()}
function pbqAnswered(q){
 if(!q.pbq)return !!exam.answers[q.id]?.length;
 const id=q.id;
 const flags={340:exam.q340?.submitted,341:exam.q341?.submitted,342:exam.q342?.submitted,343:exam.q343?.submitted,344:exam.q344?.submitted,345:exam.workstationSubmitted,346:exam.printerSubmitted?.[346],347:exam.q347?.submitted,348:exam.q348?.submitted,349:exam.q349?.submitted,350:exam.voip350?.submitted,351:exam.q351?.submitted};
 return !!flags[id] || !!exam.pbqSubmitted?.[id] || !!exam.answers[id]?.length;
}
function navigatorHTML(){return `<section class="navigator-panel" aria-label="Question Navigator"><div class="navigator-head"><h2>Question Navigator</h2><button class="secondary" onclick="questionList()">Close ×</button></div><p class="muted">Choose a question to jump to it. Green = answered or PBQ submitted, gold = bookmarked, dark outline = current.</p><div class="navigator-grid">${exam.items.map((q,i)=>`<button class="nav-number ${pbqAnswered(q)?'answered':''} ${state.bookmarks.includes(q.id)?'bookmarked':''} ${exam.index===i?'current':''}" ${exam.paused?'disabled':''} aria-label="Go to question ${i+1}" onclick="goToQuestion(${i})">${i+1}${state.bookmarks.includes(q.id)?' ★':''}</button>`).join('')}</div></section>`}
function questionList(){navigatorOpen=!navigatorOpen;renderExam()}
function goToQuestion(i){if(exam.paused)return;exam.index=i;navigatorOpen=false;renderExam()}

function exitExam(){if(!exam){showHome();return;}if(!confirm('Exit this exam? Your unfinished attempt will not be scored or saved to history.'))return;stop();exam=null;navigatorOpen=false;showHome()}
function finish(auto){if(!exam)return;if(exam.paused&&!auto)return;if(!auto&&!confirm('Are you sure you want to finish this exam? Unanswered questions will be counted as unanswered.'))return;stop();let scored=exam.items.filter(q=>q.gradable),correct=scored.filter(q=>{let a=exam.answers[q.id]||[];return a.length===q.answer.length&&a.every(x=>q.answer.includes(x))}).length,answered=exam.items.filter(q=>pbqAnswered(q)).length,elapsed=Math.round((Date.now()-exam.start)/1000),report={date:new Date().toLocaleString(),total:exam.items.length,scored:scored.length,correct,answered,elapsed,domain:{}};for(let d=1;d<=5;d++){let arr=scored.filter(q=>q.domain===d);report.domain[d]={total:arr.length,correct:arr.filter(q=>{let a=exam.answers[q.id]||[];return a.length===q.answer.length&&a.every(x=>q.answer.includes(x))}).length}}state.history.unshift(report);state.history=state.history.slice(0,100);for(let q of exam.items){let a=exam.answers[q.id]||[];if(q.gradable&&a.length){state.attempts.push({id:q.id,domain:q.domain,correct:a.length===q.answer.length&&a.every(x=>q.answer.includes(x))})}}state.attempts=state.attempts.slice(-10000);save();mode='report';let pct=scored.length?Math.round(correct/scored.length*100):0;app.innerHTML=`<h1>CompTIA A+ Core 1 (220-1201) Simulator Report</h1><p>${esc(report.date)}</p><div class="stats"><div class="stat">Answered<strong>${answered}/${exam.items.length}</strong></div><div class="stat">Automatically graded<strong>${scored.length}</strong></div><div class="stat">Correct<strong>${correct}</strong></div><div class="stat">Practice accuracy<strong>${pct}%</strong></div><div class="stat">Time<strong>${fmt(elapsed)}</strong></div></div><p class="muted">Practice percentage is not an official CompTIA scaled score. Questions without reliable source keys are excluded from accuracy.</p><h2>Domain results</h2><table><tr><th>Domain</th><th>Correct</th><th>Scored</th></tr>${D.map((d,i)=>`<tr><td>${d}</td><td>${report.domain[i+1].correct}</td><td>${report.domain[i+1].total}</td></tr>`).join('')}</table><div class="actions"><button class="primary" onclick="bookmarkIncorrect()">Bookmark all incorrect answers</button><button class="primary" onclick="exam=null;showDashboard()">Dashboard</button><button class="secondary" onclick="exam=null;showHome()">Exit</button></div>`}
function bookmarkIncorrect(){for(let q of exam.items){let a=exam.answers[q.id]||[];if(q.gradable&&!(a.length===q.answer.length&&a.every(x=>q.answer.includes(x)))&&!state.bookmarks.includes(q.id))state.bookmarks.push(q.id)}save();alert('Incorrect and unanswered gradable questions bookmarked.')}
function showDashboard(){if(exam&&mode==='exam'&&!confirm('Leave current exam?'))return;exam=null;stop();mode='dashboard';nav('dashboard');let total=state.attempts.length;app.innerHTML=`<h1>Dashboard</h1><div class="stats"><div class="stat">Questions attempted<strong>${total}</strong></div><div class="stat">Overall accuracy<strong>${total?Math.round(state.attempts.filter(x=>x.correct).length/total*100):0}%</strong></div><div class="stat">Bookmarked<strong>${state.bookmarks.length}</strong></div><div class="stat">Completed tests<strong>${state.history.length}</strong></div></div><h2>Domain Performance</h2><table><tr><th>Domain</th><th>Answered</th><th>Correct</th></tr>${D.map((d,i)=>{let a=state.attempts.filter(x=>x.domain===i+1);return `<tr><td>${i+1}. ${d}</td><td>${a.length}</td><td>${a.length?Math.round(a.filter(x=>x.correct).length/a.length*100)+'%':'—'}</td></tr>`}).join('')}</table><h2>Test History</h2><table><tr><th>Date</th><th>Questions</th><th>Accuracy</th></tr>${state.history.map(h=>`<tr><td>${esc(h.date)}</td><td>${h.total}</td><td>${h.scored?Math.round(h.correct/h.scored*100)+'%':'N/A'}</td></tr>`).join('')}</table><div class="actions"><button class="secondary" onclick="if(confirm('Delete all history and performance data?')){state.history=[];state.attempts=[];save();showDashboard()}">Reset History</button><button class="secondary" onclick="if(confirm('Clear bookmarks?')){state.bookmarks=[];save();showDashboard()}">Clear Bookmarks</button></div>`}
function showMore(){mode='more';nav('more');app.innerHTML=`<h1>About this simulator</h1><p>CompTIA A+ Core 1 (220-1201), built from the 417-page PDF you supplied. Contains ${QUESTIONS.length} numbered source questions and ${QUESTIONS.filter(x=>x.pbq).length} PBQ/image-style questions.</p><p>All question text, source answers and explanations are extracted from your PDF. Some original questions have incomplete answer keys, ambiguous objective references, or image-only interactions. Those items are displayed without inventing a correct answer. The PBQ workspace supports drag and drop and touch selection, but complex diagram hotspots cannot be automatically graded without verified solution data.</p><p>Domain labels use explicit PDF references where possible and keyword classification otherwise. Review objective assignment when a source reference is missing or inconsistent.</p><p>Progress is saved locally in this browser; no internet connection is required.</p><div class="actions"><button class="secondary" onclick="if(confirm('Reset all saved history and bookmarks?')){state={history:[],bookmarks:[],attempts:[]};save();showMore()}">Reset All Saved Data</button></div>`}
showHome();


