const q344Names=['PC 1','PC 2','Server 1','Server 2'];

const q344Starting=['192.168.1.1','192.168.1.2','192.168.1.1','192.168.1.2'];

const q344Proposed=['192.168.1.3','192.168.1.4','192.168.1.5','192.168.1.6'];

function q344State(){exam.q344??={selected:0,changes:{},submitted:false};return exam.q344}

function q344Select(i){if(exam.paused)return;q344State().selected=i;renderExam()}

function q344Change(i,v){if(exam.paused)return;q344State().changes[i]=v.trim();q344State().submitted=false;q344State().tested=false;renderExam()}

function q344Reset(){if(exam.paused)return;exam.q344={selected:0,changes:{},submitted:false};renderExam()}

function q344Mode(mode){if(exam.paused)return;q344State().mode=mode;renderExam()}

function q344Run(){if(exam.paused)return;const st=q344State(),cmd=(document.getElementById('q344-command')?.value||'').trim().toLowerCase();if(!cmd)return;st.command='';st.output=cmd;st.history=st.history||{};const i=st.selected;st.history[i]=st.history[i]||[];if(cmd==='cls'||cmd==='clear'){st.history[i]=[];st.output='';}else{st.history[i].push(cmd);if(st.history[i].length>12)st.history[i].shift();}renderExam();const input=document.getElementById('q344-command');if(input)input.focus()}

function q344Test(){if(exam.paused)return;const st=q344State();st.tested=true;renderExam()}

function q344Submit(){if(exam.paused)return;const st=q344State();st.submitted=true;st.tested=true;renderExam()}

function q344HTML(){const st=q344State(),i=st.selected,ip=q344Starting[i],mode=st.mode||'terminal';
const addresses=q344Names.map((_,j)=>(st.changes[j]||q344Starting[j]).trim());
const validIP=x=>{const a=x.split('.');return a.length===4&&a.every(n=>/^\d{1,3}$/.test(n)&&+n<=255)&&a[0]==='192'&&a[1]==='168'&&a[2]==='1'&&+a[3]>0&&+a[3]<255&&x!=='192.168.1.50'};
const checks=addresses.map(x=>validIP(x)&&addresses.filter(y=>y===x).length===1),total=checks.filter(Boolean).length;
const current=addresses[i],duplicate=addresses.filter(x=>x===current).length>1,cmd=st.output||'';
let output=cmd==='help'?'Supported commands: help, hostname, ipconfig, ipconfig /all, ping <IPv4>, cls, clear':cmd==='hostname'?q344Names[i].replace(' ',''):cmd==='ipconfig'||cmd==='ipconfig /all'?`Windows IP Configuration\nHost Name . . . . . . . . : ${q344Names[i].replace(' ','')}\nDNS Suffix Search List . . : corp.lan\n\nEthernet adapter Ethernet 1:\n   DHCP Enabled . . . . . : No\n   IPv4 Address . . . . . : ${current} (Preferred)\n   Subnet Mask . . . . . . : 255.255.255.0\n   Default Gateway . . . . : 192.168.1.50\n   DNS Servers . . . . . . : 192.168.1.50` :cmd.startsWith('ping ')?(()=>{const target=cmd.slice(5).trim(),reachable=target==='192.168.1.50'||(addresses.includes(target)&&addresses.filter(x=>x===target).length===1);return `Pinging ${target} with 32 bytes of data:\n${reachable&&!duplicate&&validIP(current)?'Reply from '+target+': bytes=32 time<1ms TTL=64':'Request timed out. Check duplicate IP addresses and network settings.'}`})():cmd===''?'':"'"+cmd+"' is not recognized as an internal or external command,\noperable program or batch file.";
return `<section class="q344"><h2>Question 344 — Network Connectivity Troubleshooting</h2><p>Investigate <b>PC 1, PC 2, Server 1, and Server 2</b>. Identify duplicate IPv4 addresses, change conflicting addresses in IPv4 properties, then verify the devices can communicate.</p><div class="q344-guide"><h3>How to use the Command terminal</h3><ol><li>Select a device below, then choose <b>Command terminal</b>.</li><li>Type <code>help</code> to see available commands, then press <b>Enter</b>.</li><li>Type <code>ipconfig /all</code> and press Enter. Compare the IPv4 address, subnet mask, and default gateway with the other devices.</li><li>Use <code>ping 192.168.1.50</code> to check the router, or ping another device's IPv4 address. A duplicate IP can cause unreliable communication.</li></ol><h3>How to use IPv4 properties</h3><ol><li>Select the affected device, then choose <b>IPv4 properties</b>.</li><li>Replace its conflicting IPv4 address with an unused address in the same subnet.</li><li>Click <b>Apply IPv4 settings</b>. Repeat for any other device needing a correction.</li><li>Return to the terminal to retest. Click <b>Test Connection</b> to check the network first, then <b>Submit Answers</b> to grade your choices.</li></ol><p class="muted">The terminal is an offline practice simulation; its output is generated by this study game.</p></div><img class="q344-image" src="assets/q344_network_original.png" alt="Original PDF network diagram: router, switch, PC 1, PC 2, Server 1, Server 2"><div class="q344-tabs">${q344Names.map((name,j)=>`<button class="secondary ${i===j?'q344-active':''}" onclick="q344Select(${j})" ${exam.paused?'disabled':''}>${name}${st.submitted?' '+(checks[j]?'✓':'✕'):''}</button>`).join('')}</div><div class="q344-tabs"><button class="secondary ${mode==='terminal'?'q344-active':''}" onclick="q344Mode('terminal')">Command terminal</button><button class="secondary ${mode==='ipv4'?'q344-active':''}" onclick="q344Mode('ipv4')">IPv4 properties</button></div>${mode==='terminal'?`<div class="q344-win-cmd"><div class="q344-win-title"><span class="q344-win-icon">C:\\_</span><span>Administrator: Command Prompt — ${q344Names[i]}</span><span class="q344-window-controls">─ &nbsp; □ &nbsp; ×</span></div><div class="q344-console" role="region" aria-label="Windows command prompt"><div class="q344-console-lines">Microsoft Windows [Version 10.0.19045.XXXX]<br>(c) Microsoft Corporation. All rights reserved.<br><br>${(st.history?.[i]||[]).slice(-10).map((entry,j)=>{const prompt='C:\\Users\\'+q344Names[i].replace(' ','')+'&gt;'+esc(entry);return '<div class="q344-cmd-entry">'+prompt+'</div>'}).join('')}${cmd?'<div class="q344-cmd-result">'+esc(output).replace(/\n/g,'<br>')+'</div><br>':''}</div><form class="q344-prompt" onsubmit="event.preventDefault();q344Run()"><label for="q344-command">C:\\Users\\${q344Names[i].replace(' ','')}&gt;</label><input id="q344-command" autocomplete="off" spellcheck="false" aria-label="Windows command" value="${esc(st.command||'')}" placeholder="" ${exam.paused?'disabled':''}></form></div><p class="q344-cmd-hint">Type a command and press <b>Enter</b>. Try <code>ipconfig /all</code>, <code>ping 192.168.1.50</code>, or <code>cls</code> to clear the screen. This is an offline Windows-style simulation.</p></div>`:`<div class="q344-remediation"><h3>${q344Names[i]} — Internet Protocol Version 4 (TCP/IPv4) Properties</h3><label>IP address<input id="q344-ip" type="text" value="${esc(current)}" ${exam.paused?'disabled':''}></label><label>Subnet mask<input type="text" value="255.255.255.0" disabled></label><label>Default gateway<input type="text" value="192.168.1.50" disabled></label><p class="muted">Choose a unique IP in 192.168.1.0/24. The original reference indicates conflicting IP addresses; several unique replacements are valid.</p><button class="primary" onclick="q344Change(${i},document.getElementById('q344-ip').value)" ${exam.paused?'disabled':''}>Apply IPv4 settings</button></div>`}<div class="actions"><button class="secondary" onclick="q344Reset()" ${exam.paused?'disabled':''}>Reset All</button><button class="secondary" onclick="q344Test()" ${exam.paused?'disabled':''}>Test Connection</button><button class="primary" onclick="q344Submit()" ${exam.paused?'disabled':''}>Submit Answers</button></div>${st.tested?`<div class="review" aria-live="polite"><b>Connection Test — ${total}/4 devices pass</b><p>${total===4?'All four devices have unique, valid host addresses in the practice network.':'Connectivity problems detected. Check each device for duplicate, reserved, or invalid IPv4 addresses.'}</p>${q344Names.map((name,j)=>`<p class="${checks[j]?'q343-good':'q343-bad'}">${checks[j]?'✓ Pass':'✕ Fail'} — ${name}: ${esc(addresses[j])}</p>`).join('')}<p class="muted">Offline simulation; this does not contact a real network.</p></div>`:''}${st.submitted?`<div class="review" aria-live="polite"><b>PBQ Review — Your Answers vs. Correct Answers</b><table class="q344-compare"><thead><tr><th>Device</th><th>Your answer</th><th>Example correct answer</th><th>Result</th></tr></thead><tbody>${q344Names.map((name,j)=>`<tr><td>${name}</td><td>${esc(addresses[j])}</td><td>${q344Proposed[j]}</td><td class="${checks[j]?'q343-good':'q343-bad'}">${checks[j]?'✓ Correct':'✕ Incorrect'}</td></tr>`).join('')}</tbody></table><p><b>Scoring:</b> Other unique, usable IP addresses in the same subnet are also accepted. The example values are not the only valid choices.</p><p><b>Why:</b> PC 1 and Server 1 originally share 192.168.1.1, and PC 2 and Server 2 share 192.168.1.2. Duplicate IPs disrupt communication.</p><p><b>Remember Tip:</b> Compare <code>ipconfig /all</code> across hosts before assigning unused addresses; then verify with <code>ping</code>.</p></div>`:''}'}</section>`}

/* Question 343: nine-device troubleshooting hotspot, grounded in the supplied marked reference. */

const q343Devices=[
 ['Laptop 1 — dark screen','Swollen battery','A replacement is required'],
 ['Laptop 2 — boot error','Cannot locate boot partition','Enter the BIOS and configure changes'],
 ['Laptop 3 — startup error','Overheating','Disable overclocking in the CPU'],
 ['Phone 1 — purple screen','Burn in','A replacement is required'],
 ['Projector 1 — distorted image','Keystoning','Adjust the display angle settings'],
 ['Projector 2 — incorrect source','Wrong input selected','Switch the display input'],
 ['Phone 2 — battery problem','Battery performance','A replacement is required'],
 ['Monitor 1 — no signal','Wrong input selected','Switch the display input'],
 ['Monitor 2 — persistent image','Burn in','A replacement is required']
];

const q343Issues=['Battery performance','Burn in','Cannot locate boot partition','Fuzzy image','Incorrect contrast settings','Keystoning','Overheating','Swollen battery','Wrong input selected'];

const q343Solutions=['Adjust the refresh rate settings','Adjust the display angle settings','Clean the lens','Disable overclocking in the CPU','Enter the BIOS and configure changes','A replacement is required','Switch the display input','Upgrade the hard drive'];

function q343State(){exam.q343??={picks:{},submitted:false};return exam.q343}

function q343Set(i,kind,val){if(exam.paused)return;let st=q343State();st.picks[i]??={};st.picks[i][kind]=val;st.submitted=false}

function q343Reset(){if(exam.paused)return;exam.q343={picks:{},submitted:false};renderExam()}

const q343Guidance=[
 ['A swollen battery physically expands as gases accumulate inside the cell. The pressure can deform a laptop chassis or lift the trackpad. A new battery is needed because software settings cannot reverse swelling.','Swelling is a safety warning: stop charging, power down, and arrange safe battery replacement. Never puncture or compress the pack.'],
 ['A missing boot partition prevents firmware from locating the files needed to start the operating system. BIOS/UEFI settings let you verify that the correct disk is detected and selected as the boot device.','Check disk detection and boot order before reinstalling an operating system; a missing drive and an incorrect boot target are different problems.'],
 ['Excessive heat can make the processor throttle or shut down during startup. Disabling CPU overclocking reduces power draw and heat production, helping the system operate within its thermal limits.','Clock frequency, voltage, and cooling interact. If startup fails under load, return CPU settings to stable defaults and inspect airflow.'],
 ['Burn-in leaves a persistent ghost image because some display pixels age unevenly. A replacement is required when the panel has permanent image retention; switching apps cannot restore damaged pixels.','A shadow that stays in the same location across unrelated screens points to panel damage rather than a software window.'],
 ['Keystoning makes the projected rectangle appear trapezoidal when the projector is tilted relative to the screen. Correcting the display angle aligns the light path and restores the rectangular shape.','A trapezoid is a geometry problem; a blurry but rectangular image suggests focus or lens cleanliness instead.'],
 ['A projector can be working while showing the wrong source. Switching the display input selects the port carrying the intended computer signal rather than altering image sharpness or contrast.','Trace the cable to HDMI, VGA, or another port, then select that input; a powered projector does not guarantee the right source is active.'],
 ['Poor battery performance means the phone can no longer store enough usable charge for normal operation. Replacing a worn battery restores capacity when age-related degradation is the cause.','Rapid discharge and short runtime point to battery health; check background power use before deciding the cell itself is worn.'],
 ['A monitor with no picture may be listening to an unused video port. Switching the display input to the port connected to the computer restores the signal without replacing working hardware.','Match the input menu to the actual cable connection. “No signal” differs from a backlight or panel failure.'],
 ['Burn-in on a monitor is persistent image retention from uneven pixel wear. A replacement is needed for permanent panel damage; changing the refresh rate will not repair aged pixels.','If the same faint shape remains after changing sources and displaying a plain background, investigate permanent retention.']
];
function q343HTML(){let st=q343State();let correct=0;let blocks=q343Devices.map(([name,issue,solution],i)=>{let pick=st.picks[i]||{};let a=pick.issue===issue,b=pick.solution===solution;if(a&&b)correct++;let opts=(arr,value,kind)=>`<select aria-label="${esc(name)} ${kind}" onchange="q343Set(${i},'${kind}',this.value)" ${exam.paused?'disabled':''}><option value="">— Select ${kind} —</option>${arr.map(x=>`<option value="${esc(x)}" ${value===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;return `<div class="q343-device"><h3>${esc(name)}</h3><label>Issue ${opts(q343Issues,pick.issue,'issue')}</label><label>Solution ${opts(q343Solutions,pick.solution,'solution')}</label>${st.submitted?`<div class="q343-result"><p class="${a?'q343-good':'q343-bad'}">${a?'Correct issue':'Incorrect issue'} — ${esc(pick.issue||'Not selected')}${a?'':`<br>Correct: ${esc(issue)}`}</p><p class="${b?'q343-good':'q343-bad'}">${b?'Correct solution':'Incorrect solution'} — ${esc(pick.solution||'Not selected')}${b?'':`<br>Correct: ${esc(solution)}`}</p><p><b>Why this diagnosis and solution fit:</b> ${esc(q343Guidance[i][0])}</p><p><b>Remember Tip:</b> ${esc(q343Guidance[i][1])}</p></div>`:''}</div>`}).join('');return `<section class="q343"><h2>Question 343 — Diagnose Device Issues</h2><p>Click each device's issue and solution dropdown. Options may be reused. Match the nine devices to the problems shown in the original PDF.</p><details open><summary>Original device diagram — Question 343</summary><img class="q343-ref" src="assets/q343_devices.png" alt="Original question 343 device layout"></details><details><summary>View original issue and solution dropdown options (no answers marked)</summary><img class="q343-ref" src="assets/q343_options.png" alt="Question 343 dropdown menu choices"></details><div class="q343-grid">${blocks}</div><div class="actions"><button class="secondary" onclick="q343Reset()" ${exam.paused?'disabled':''}>Reset All</button><button class="primary" onclick="q343State().submitted=true;renderExam()" ${exam.paused?'disabled':''}>Submit Answers</button></div>${st.submitted?`<div class="review"><b>PBQ Review — ${correct} of 9 devices fully correct</b><p>Each device above shows your issue and solution selections alongside the correct selections, a device-specific explanation, and a practical Remember Tip.</p><details><summary>Show marked answer reference</summary><img class="q343-ref" src="assets/q343_answer.png" alt="Marked answer image supplied for question 343"></details></div>`:''}</section>`}

/* Question 348 — diagnose a gaming PC that locks up shortly after startup. */

const q348Causes=['Overheating','Component incompatibility','Insufficient power','Overclocking'];

const q348Fixes=['Replace PSU with higher wattage model','Update motherboard firmware','Install larger radiator','Lower CPU clock speed','Increase CPU multiplier','Run CHKDSK on NVMe drive','Replace thermal paste','Decrease CPU voltage','Raise memory frequency','Switch motherboard for micro-ATX form factor','Decrease memory module frequency','Replace GPU with lower performance model'];

function q348State(){exam.q348??={cause:'',fix:'',submitted:false};return exam.q348}

function q348Set(k,v){let st=q348State();st[k]=v;st.submitted=false;renderExam()}

function q348Reset(){exam.q348={cause:'',fix:'',submitted:false};renderExam()}

function q348HTML(){let st=q348State(),goodCause=st.cause==='Overclocking',goodFix=st.fix==='Lower CPU clock speed';const pick=(kind,opts,value)=>`<select aria-label="${kind}" onchange="q348Set('${kind}',this.value)" ${exam.paused?'disabled':''}><option value="">— Select ${kind} —</option>${opts.map(o=>`<option value="${esc(o)}" ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;return `<section class="q348"><h2>Question 348 — Gaming PC Lockup Troubleshooting</h2><p>Inspect the PC components and BIOS system information in the original question image. Identify the most likely cause of the lockup and select the best resolution.</p><img class="q348-diagram" src="assets/q348_original.png" alt="Original question 348 gaming computer diagram with CPU, cooling, memory, motherboard, storage, power supply and BIOS system information"><div class="q348-fields"><label><b>Cause</b>${pick('cause',q348Causes,st.cause)}</label><label><b>Resolution</b>${pick('fix',q348Fixes,st.fix)}</label></div><div class="actions"><button class="secondary" onclick="q348Reset()" ${exam.paused?'disabled':''}>Reset PBQ</button><button class="primary" onclick="q348State().submitted=true;renderExam()" ${exam.paused?'disabled':''}>Submit Answers</button></div>${st.submitted?`<div class="review" aria-live="polite"><b>PBQ Review</b><p class="${goodCause?'q343-good':'q343-bad'}">${goodCause?'✓ Correct':'✕ Incorrect'} cause: ${esc(st.cause||'Not selected')}${goodCause?'':'. Correct: Overclocking.'}</p><p class="${goodFix?'q343-good':'q343-bad'}">${goodFix?'✓ Correct':'✕ Incorrect'} resolution: ${esc(st.fix||'Not selected')}${goodFix?'':'. Correct: Lower CPU clock speed.'}</p><p><b>Explanation:</b> Excessive CPU clock speed can make a system unstable and cause freezes after startup. Reducing the CPU clock speed returns it toward stable operating settings.</p><p><b>Remember tip:</b> Clock speed boosts performance only while the processor remains stable; higher frequency also increases power and cooling demands.</p><details><summary>View your supplied marked answer reference</summary><img class="q348-diagram" src="assets/q348_answer_reference.png" alt="Marked answer reference showing overclocking and lower CPU clock speed"></details><p class="muted">Graded against the marked reference image you supplied.</p></div>`:''}</section>`}


/* Question 349: image-token UPS power placement. */

const q349Names=['Cable Modem','Computer','Monitor','Printer','Scanner','Wi-Fi Router'];

const q349Correct=[2,2,2,1,1,2];

function q349State(){exam.q349??={slots:Array(18).fill(-1),sourceSurge:'Wall Outlet',sourceUPS:'Wall Outlet',selected:-1,submitted:false};return exam.q349}

function q349Select(i){const st=q349State();st.selected=i;renderExam()}

function q349Place(slot,i){const st=q349State();if(i===undefined)i=st.selected;if(i<0)return;st.slots=st.slots.map(v=>v===i?-1:v);st.slots[slot]=i;st.selected=-1;st.submitted=false;renderExam()}

function q349Drop(e,slot){e.preventDefault();const i=Number(e.dataTransfer.getData('text/plain'));if(Number.isInteger(i)&&i>=0&&i<6)q349Place(slot,i)}

function q349Clear(slot){const st=q349State();st.slots[slot]=-1;st.submitted=false;renderExam()}

function q349Reset(){exam.q349=null;renderExam()}

function q349HTML(){const st=q349State(),correct=q349Correct.every((col,i)=>st.slots.some((v,j)=>v===i&&Math.floor(j/6)===col))&&st.sourceSurge==='Wall Outlet'&&st.sourceUPS==='Wall Outlet';
 const tile=i=>`<img src="assets/q349_device_${i}.png" alt="${q349Names[i]}" draggable="false">`;
 const group=(col,title)=>`<div class="q349-column"><h3>${title}</h3>${col?`<label>Power Source <select aria-label="${title} power source" onchange="q349State().${col===1?'sourceSurge':'sourceUPS'}=this.value;q349State().submitted=false;renderExam()"><option ${st[col===1?'sourceSurge':'sourceUPS']==='Wall Outlet'?'selected':''}>Wall Outlet</option><option ${st[col===1?'sourceSurge':'sourceUPS']==='Surge Protector'?'selected':''}>Surge Protector</option><option ${st[col===1?'sourceSurge':'sourceUPS']==='UPS'?'selected':''}>UPS</option></select></label>`:'<div class="q349-source-spacer"></div>'}${Array.from({length:6},(_,r)=>{let j=col*6+r,i=st.slots[j];return `<div class="q349-slot" ondragover="event.preventDefault()" ondrop="q349Drop(event,${j})" onclick="q349Place(${j})" aria-label="${title} socket ${r+1}">${i<0?'<span class="q349-empty">?</span>':`${tile(i)}<button class="q349-clear" title="Remove" onclick="event.stopPropagation();q349Clear(${j})">×</button>`}</div>`}).join('')}</div>`;
 return `<section class="q349"><h2>Question 349 — SOHO Power Protection</h2><p>Drag each original device image into one socket, or tap an image and then a socket. Each device can be placed once. Set the power source for both the surge protector and UPS.</p><div class="q349-board">${group(0,'Wall Outlet')}${group(1,'Surge Protector')}${group(2,'UPS')}<div class="q349-column q349-palette"><h3>Drag &amp; Drop</h3>${q349Names.map((n,i)=>`<div class="q349-token ${st.selected===i?'q349-selected':''}" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${i}')" onclick="q349Select(${i})" title="${n}">${tile(i)}</div>`).join('')}</div></div><div class="actions"><button class="secondary" onclick="q349Reset()">Reset All</button><button class="primary" onclick="q349State().submitted=true;renderExam()">Submit Answers</button></div>${st.submitted?`<div class="review"><b>PBQ Review — ${correct?'All correct':'Review your connections'}</b><p>Surge protector: ${st.sourceSurge==='Wall Outlet'?'✓':'✕'} Wall Outlet. UPS: ${st.sourceUPS==='Wall Outlet'?'✓':'✕'} Wall Outlet.</p>${q349Names.map((n,i)=>{let slot=st.slots.findIndex(x=>x===i),col=slot<0?-1:Math.floor(slot/6),ok=col===q349Correct[i];return `<p>${ok?'✓ Correct':'✕ Incorrect'} — ${n}: ${col<0?'Not placed':['Wall Outlet','Surge Protector','UPS'][col]}${ok?'':`. Correct: ${['Wall Outlet','Surge Protector','UPS'][q349Correct[i]]}`}</p>`}).join('')}<p><b>Explanation:</b> The UPS keeps the computer, monitor, modem and router powered briefly during an outage so work can be saved. The printer and scanner can use surge protection without draining UPS battery runtime.</p><p><b>Remember tip:</b> Reserve battery-backed outlets for equipment needed to save work and maintain connectivity.</p></div>`:''}</section>`}




